export default [{"id":"nested-radius","title":"嵌套圆角","english":"Nested radius","cover":"/assets/source-media/2115469767650021796-1.jpg","keywords":"嵌套圆角 nested radius 圆角也有秩序：让内外轮廓拥有同一个圆心。 当一个圆角容器包住另一个元素时，内层圆角应随内缩距离变小。对于等距内缩的普通圆角，内圆角 r = 外圆角 r − 间距 p。这样转角处的留白才会与直边处一样均匀。 圆角 布局 css 004 4 999 个小技巧"},{"id":"design-tokens","title":"设计变量","english":"Design tokens","cover":"/assets/source-media/2121615225816494303-1.jpg","keywords":"设计变量 design tokens 为颜色、间距和圆角命名，让设计拥有共同的词汇。 design token 是具有名字的设计决策，例如 surface、text-muted、space-4。组件引用名字，而不是各自写一套数值。修改一个语义变量，可以让相关组件保持一致。 系统 一致性 变量"},{"id":"skeuomorphism","title":"拟物设计","english":"Skeuomorphism","cover":"/assets/source-media/2118371924594348505-1.jpg","keywords":"拟物设计 skeuomorphism 用真实世界的光、边缘和材质，解释一个数字物件。 拟物设计借用实体物件的外观线索，让数字界面具有可感知的材质和层次。本站从 kubai 对 portrait 界面的点评出发，演示描边、浅渐变和光影怎样共同建立体积。 材质 光影 层次"},{"id":"continuous-corners","title":"连续圆角","english":"Continuous corners","cover":"/assets/source-media/2115469767650021796-1.jpg","keywords":"连续圆角 continuous corners 让直边进入转角的过程更平顺，轮廓更柔和。 普通圆角由直线接圆弧，连接处的曲率会发生跳变。连续圆角通过不同的曲线形状缓和这个变化。超椭圆是构建这类柔和轮廓的一种方法，并不代表任意参数都具备相同效果。 超椭圆 css 形状 004 4 999 个小技巧"},{"id":"spacing-scale","title":"间距体系","english":"Spacing scale","cover":"/assets/source-media/2121615225816494303-1.jpg","keywords":"间距体系 spacing scale 距离表达关系。相关的靠近，不相关的留出呼吸。 间距体系是一组有限、重复使用的距离。4px 可以作为基础单位，但真正决定距离的是信息之间的关系：标签和输入框更近，两组表单更远，页面章节之间最远。 间距 布局 亲密性"},{"id":"continuity","title":"界面连续性","english":"UI continuity","cover":"/assets/source-media/2120320609255043510-1.jpg","keywords":"界面连续性 ui continuity 状态变了，用户仍然知道自己刚刚操作了什么。 界面连续性让用户在状态切换时保留对元素身份、位置和关系的理解。例如按钮展开成菜单时，菜单从触发位置生长出来，比远处突然出现一个面板更容易追踪。 动效 状态 交互 015 15 999 个小技巧"},{"id":"toast","title":"轻提示","english":"Toast","cover":"/assets/source-media/2120682993563922586-1.jpg","keywords":"轻提示 toast 告诉用户「刚才的操作有结果了」，然后轻轻离开。 toast 是与当前操作紧密相关的短暂反馈，例如复制完成。它通常自动消失，可以附带撤销入口。对用户必须处理的问题，应使用持续可见的提示，而不是让信息随 toast 一起消失。 反馈 提示 交互 016 16 999 个小技巧"},{"id":"notification","title":"通知","english":"Notification","cover":"/assets/source-media/2120682993563922586-1.jpg","keywords":"通知 notification 事情值得你知道，但不一定值得打断你。 通知可以由系统事件或他人的动作触发，与当前操作不一定直接相关。这里讨论的是产品内通知：消息会保留到用户处理或关闭，必要时可以在通知中心再次找到。 反馈 信息 状态 016 16 999 个小技巧"},{"id":"holographic","title":"镭射质感","english":"Holographic","cover":"/assets/source-media/2121892029403922717-1.jpg","keywords":"镭射质感 holographic 把角度变成颜色，让一张卡片像真实藏品。 界面中的镭射效果通过随观察角度变化的色彩与高光，模拟全息箔材质。kubai 的卡片案例把倾斜、亮边和深度层次组合在一起。 光影 3d 材质 018 18 999 个小技巧"},{"id":"ascii","title":"字符艺术","english":"ASCII art","cover":"/assets/source-media/2115091203465290087-1.jpg","keywords":"字符艺术 ascii art 用有限的字符密度，重建图像的明暗和轮廓。 字符艺术用字形代替像素。把图像切成采样格，再根据每格亮度选择疏密不同的字符，就能保留轮廓。原帖第 003 期说明了字符采样，并提供可调参数。kubai 另转引 @imperry 的首页动画作为应用案例。 字符 复古 图像 003 3 999 个小技巧"},{"id":"alignment","title":"对齐的秩序","english":"Alignment","cover":"/assets/source-media/2115379248013717822-1.jpg","keywords":"对齐的秩序 alignment 先建立一条共同的线，信息就有了可以依靠的骨架。 对齐给元素建立共同的边缘或基线。列表里的标题、说明与操作如果共享稳定的对齐规则，读者就能更快地扫读和比较。这是本站对原帖排版建议的延伸讲解。 对齐 布局 排版"},{"id":"typography-scale","title":"字号与层级","english":"Type scale","cover":"/assets/source-media/2115379248013717822-1.jpg","keywords":"字号与层级 type scale 用有限的文字角色，让重要的先被看见。 字号体系把标题、正文、标签和辅助信息分配到有限的文字角色。层级由字号、字重、行高和空间共同建立，不能只靠把所有标题放大。本站将原帖的字号建议整理为实践步骤。 字体 排版 层级"},{"id":"progressive-disclosure","title":"渐进披露","english":"Progressive disclosure","cover":"/assets/source-media/2121615225816494303-1.jpg","keywords":"渐进披露 progressive disclosure 先给足以开始的信息，再让细节在需要时出现。 渐进披露把低频细节放到后续层级，让当前任务保持清楚。本站从原帖关于说明文案的建议延伸这一概念：关键操作条件必须可见，补充背景则可以按需展开。 文案 认知负担 交互"},{"id":"drag-feedback","title":"拖拽的反馈","english":"Drag feedback","cover":"/assets/source-media/2115823717024735708-1.jpg","keywords":"拖拽的反馈 drag feedback 拿起、经过、落下，每一步都告诉用户下一步会发生什么。 可用的拖拽排序需要区分被拿起的对象、当前落点和附近对象的避让。动效表达空间关系，而排序结果仍然由明确的数据顺序控制。 拖拽 动效 反馈 005 5 999 个小技巧"},{"id":"book-reveal","title":"翻页式展开","english":"Book reveal","cover":"/assets/source-media/2116198373040759107-1.jpg","keywords":"翻页式展开 book reveal 把预览藏在封面之后，用翻开这个动作表达更多内容。 翻页式展开把卡片分成封面与内页，以书脊为转轴产生层次。封面先动、内页随后展开，形成内容藏在物件内部的空间暗示。 动效 3d 卡片 006 6 999 个小技巧"},{"id":"semantic-components","title":"按语义选组件","english":"Semantic components","cover":"/assets/source-media/2121615225816494303-1.jpg","keywords":"按语义选组件 semantic components 先说清用户在做什么，再决定界面应该长什么样。 组件的形状之外，还有交互承诺：链接去往一个位置，按钮触发一个动作，开关改变一个持续状态。本站以原帖关于组件语义的建议为起点，补充常见选择规则。 组件 语义 ux"},{"id":"tactile-buttons","title":"有触感的按钮","english":"Tactile buttons","cover":"/assets/source-media/2114378773655326873-1.jpg","keywords":"有触感的按钮 tactile buttons 用光影和按压状态，表现可以触碰的表面。 按钮的实体感来自明暗、轮廓和按压反馈。原帖将同一语言应用到五种按钮层级，主要动作更突出，次要动作逐步减轻。 按钮 拟物 反馈 001 1 999 个小技巧"},{"id":"cascade-safe-zone","title":"级联菜单安全区","english":"Menu aim","cover":"/assets/source-media/2114729985143677258-1.jpg","keywords":"级联菜单安全区 menu aim 给斜向移动的鼠标留一条进入子菜单的路。 父菜单和子菜单横向分列时，指针可能斜穿过其他行。用指针前一位置与子菜单近侧两个角形成三角区，判断用户是否正在朝子菜单移动。 菜单 光标 延时 002 2 999 个小技巧"},{"id":"ordered-dither","title":"有序抖动","english":"Ordered dithering","cover":"/assets/source-media/2115091203465290087-1.jpg","keywords":"有序抖动 ordered dithering 用规则颗粒模拟有限色阶，保留明暗变化。 有序抖动把图像限制在少数色阶，通过重复阈值图案分布亮暗像素。原帖使用 bayer 矩阵，让颗粒尺寸与色阶数量可以独立调节。 dither 像素 纹理 003 3 999 个小技巧"},{"id":"mixed-typesetting","title":"中英混排","english":"Mixed-language typesetting","cover":"/assets/source-media/2116555064227811412-1.jpg","keywords":"中英混排 mixed-language typesetting 用真实文案检查中英文、长词与标点的断行。 同一个容器在不同语言下会出现不同的字宽和断行。原帖建议结合实际布局选择文案，并用 css 处理对齐、句读与行宽。 排版 i18n 换行 007 7 999 个小技巧"},{"id":"wiki-navigation","title":"文档与章节导航","english":"Documentation navigation","cover":"/assets/source-media/2116911391437443471-1.jpg","keywords":"文档与章节导航 documentation navigation 让长文档在宽屏和窄屏上都能快速跳转。 把站点导航、当前文章和章节目录分开。桌面给较长目录独立滚动空间，移动端把章节入口收进容易找到的控件里。 wiki 目录 响应式 008 8 999 个小技巧"},{"id":"overlay-choice","title":"提示框、气泡与弹窗","english":"Overlay choice","cover":"/assets/source-media/2117314098165862612-1.jpg","keywords":"提示框、气泡与弹窗 overlay choice 按内容和任务选浮层：解释、局部操作、确认或完整流程。 tooltip 提供简短说明。popover 能承载局部操作。dialog 用于需要集中处理的任务，drawer 可在工作时保留上下文；主要任务也可以成为独立页面。 tooltip popover dialog drawer 009 9 999 个小技巧"},{"id":"liquid-glass","title":"液态玻璃","english":"Liquid glass","cover":"/assets/source-media/2117782193108082923-1.jpg","keywords":"液态玻璃 liquid glass 层叠透色、边缘高光和折射，建立通透的界面材质。 原帖将材质拆成背景处理、阴影、折射、着色、高光和文字处理。本站示意聚焦背景与层次，折射应依据平台和性能预算另外评估。 玻璃 折射 材质 010 10 999 个小技巧"},{"id":"motion-easing","title":"动画缓动","english":"Motion easing","cover":"/assets/source-media/2118143759984803898-1.jpg","keywords":"动画缓动 motion easing 用速度变化让入场、位移和退场各有恰当节奏。 缓动曲线决定时间与完成进度的关系。减速曲线可让浮层迅速出现后稳定落位，缓入缓出可让位置变化两端平稳。 动画 缓动 速度曲线 011 11 999 个小技巧"},{"id":"message-bubbles","title":"消息气泡材质","english":"Chat bubble material","cover":"/assets/source-media/2118508433704169726-1.jpg","keywords":"消息气泡材质 chat bubble material 给聊天界面选择一套表面语言和匹配的反馈。 原帖以磨砂、像素、aqua、共享渐变、拟物和纯色六种方案探索气泡。材质也要服务发言方识别、文本阅读和连续消息分组。 对话 气泡 材质 012 12 999 个小技巧"},{"id":"halo-ripple","title":"扩散光环","english":"Halo ripple","cover":"/assets/source-media/2119359092334743735-1.jpg","keywords":"扩散光环 halo ripple 让光环从触发位置扩散，为低频动作提供空间反馈。 原帖演示把光环、局部透镜扭曲、轻微色散与边线反光结合在一起。简化时可先用单层透明环表达扩散方向。 冲击波 光环 动效 013 13 999 个小技巧"},{"id":"exit-motion","title":"退场与补位","english":"Exit motion","cover":"/assets/source-media/2119831380276523207-1.jpg","keywords":"退场与补位 exit motion 元素退出时，让它的位置和相邻内容一起发生可追踪的变化。 退场动效既描述移除对象，也交代空位如何被填补。原帖探索多种表现方式，日常列表可以用简短淡出和自然补位表达同一因果。 退场 删除 列表 014 14 999 个小技巧"},{"id":"loading-states","title":"等待状态","english":"Loading states","cover":"/assets/source-media/2121449185014845794-1.jpg","keywords":"等待状态 loading states 按任务时间和进度可知程度选择等待反馈。 短操作适合在触发处标记忙碌，已知布局可用骨架占位，可量化的长任务显示真实进度。非常短的等待可延后提示出现，避免闪烁。 skeleton spinner progress 等待 017 17 999 个小技巧"},{"id":"optimistic-ui","title":"乐观更新","english":"Optimistic UI","cover":"/assets/source-media/2121449185014845794-1.jpg","keywords":"乐观更新 optimistic ui 对可逆且成功率高的动作，先反馈，再与服务器确认。 界面先显示预期结果，同时发送保存请求。若保存失败，恢复真实状态并说明如何重试。原帖把它归入等待体验的反馈策略。 异步 回滚 状态 017 17 999 个小技巧"},{"id":"scroll-cards","title":"卡片滚动叙事","english":"Scroll-driven cards","cover":"/assets/source-media/2122492414598459820-1.jpg","keywords":"卡片滚动叙事 scroll-driven cards 让卡片跟随滚动位置，展开、叠放或切换焦点。 原帖展示层叠、飞出、横向展廊、封面轮播和图片展开。共同点是滚动进度直接决定画面，暂停时停在当前状态，反向时顺应回退。 滚动 卡片 作品集 019 19 999 个小技巧"},{"id":"optical-alignment","title":"光学对齐","english":"Optical alignment","cover":"/assets/source-media/2122514434069537097-1.jpg","keywords":"光学对齐 optical alignment 元素的几何中心与看起来的中心有时不在同一处。 尖角、不对称轮廓和字形的视觉重量会偏离边界框中心。原帖推荐观察模糊后的形状，抓住较大的明暗区域再微调。 图标 视觉重心 对齐"},{"id":"onboarding-preview","title":"上手引导的实时预览","english":"Live onboarding preview","cover":"/assets/source-media/2120033693012291853-1.jpg","keywords":"上手引导的实时预览 live onboarding preview 用户一选，预览就反映选择对产品的实际影响。 原帖建议把选择与界面结果放在同一个过程里，并用步骤关系交代进度。实时反馈应回答「这个选项会改变什么」。 onboarding 预览 步骤"},{"id":"bento-grid","title":"动态便当布局","english":"Animated Bento grid","cover":"/assets/source-media/2115393082472681875-1.jpg","keywords":"动态便当布局 animated bento grid 让每个格子说明一个真实功能，并用大小表达优先级。 bento 以共用网格组合大小不同的内容块。原帖给功能格加入小动画，用局部演示说明用户能完成什么。 bento 网格 功能演示"},{"id":"icon-states","title":"功能图标的状态","english":"Icon states","cover":"/assets/source-media/2117125759487934952-1.jpg","keywords":"功能图标的状态 icon states 用成组图形和明确名称表达开启、关闭、展开与禁用。 功能图标延续控件语义。原帖提出用线性、实心和带斜线等变体表达状态，文字或辅助技术也应能读到状态。 图标 开关 语义"},{"id":"icon-simplification","title":"图标的体积与简化","english":"Icon simplification","cover":"/assets/source-media/2115674219602452656-1.jpg","keywords":"图标的体积与简化 icon simplification 减掉次要体积线索，让小图标保留清楚的主轮廓。 原帖从 ai 生成图标出发，建议减少不必要的高光、阴影和纹理，用更简单的色阶建立主体。 图标 渐变 小尺寸"},{"id":"glass-fallback","title":"玻璃材质的回退","english":"Glass effect fallback","cover":"/assets/source-media/2118292026756321720-1.jpg","keywords":"玻璃材质的回退 glass effect fallback 先让控件在基础样式中可读，再按能力增加材质效果。 原帖介绍 glasswork 对浏览器和视频背景的适配。本站把这一思路整理成层层增强的做法，先保证填充和文字，再加入滤镜等视觉层。 玻璃 兼容 性能"},{"id":"graphic-halftone","title":"半调纹理","english":"Halftone texture","cover":"/assets/source-media/2114628102458663022-1.jpg","keywords":"半调纹理 halftone texture 用有限的点阵密度表达影调，呈现印刷式颗粒。 半调用重复单元中的点大小、密度或覆盖面积表现明暗。kubai 点评一组落地页卡片时，把半调和 ascii、dither 视作不同的纹理选项。 半调 印刷 图像"},{"id":"choice-controls","title":"选择控件的取舍","english":"Choice controls","cover":"/assets/source-media/2123217190052827633-1.jpg","keywords":"选择控件的取舍 choice controls 先看选择何时生效，再看它是设置一个值，还是执行一个动作。 在设置里拨动「允许通知」，用户预期它立即生效。表单里的订阅选项则可能要等保存后才生效。两者都只有选与不选两种状态，提交时机决定了控件给人的承诺。 表单 开关 复选框 单选 下拉菜单 分段选择 020 20 999 个小技巧"}];